INSERT INTO "doc_schedule" VALUES('20210729000388','01569102','2021-08-19','2021-08-19','19일 | 인터넷 공고, 주1) | 수요예측일시 | 2021년 08월 19일(목) ~ 20일(금)09:00 ~ 17:00 (한국시간기준','ok',6,'2026-10-24T17:04:04+09:00','KOSDAQ','''코스닥시장'' 86회, ''유가증권시장'' 20회',NULL,NULL,'일반상장법인 3',NULL,NULL,NULL,NULL,NULL,NULL);
